import click
from click.testing import CliRunner
from click.shell_completion import CompletionItem, ShellComplete


class CustomShellComplete(ShellComplete):
    name = "custom"
    source_template = ""

    def get_completion_args(self):
        return self._args, self._pos

    def format_completion(self, item):
        return item.value


def test_allow_extra_args_false_kills_mutant():
    @click.group()
    def cli():
        pass

    @cli.command()
    @click.argument("arg")
    def cmd(arg):
        click.echo(arg)

    runner = CliRunner()
    # Invoke with extra args - original allows them, mutant doesn't
    result = runner.invoke(cli, ["cmd", "value1", "extra"], prog_name="cli")
    # Original: extra args allowed, so command runs and echoes "value1"
    # Mutant: extra args not allowed, so it errors
    assert result.exit_code == 0
    assert result.output.strip() == "value1"

import pytest
from jinja2.environment import Environment
from jinja2.ext import Extension
from jinja2.lexer import TokenStream


class StreamChangingExtension(Extension):
    def preprocess(self, source, name, filename=None):
        return source

    def filter_stream(self, stream):
        # Return a plain list of tokens instead of a TokenStream
        return list(stream)


def test_extension_filter_stream_returns_list():
    env = Environment(extensions=[StreamChangingExtension])
    # This should trigger the code path where filter_stream returns a non-TokenStream
    env.parse("Hello {{ name }}!")

