from marshmallow import Schema, fields

class MySchema(Schema):
    attr = fields.Raw(attribute="attr")
    other = fields.Raw(attribute="attr2")

def test_duplicate_attribute_detection():
    schema = MySchema()
    data = {"attr": 1, "other": 2}
    with pytest.raises(ValueError, match="The attribute argument for one or more fields collides"):
        schema.load(data)

import pytest
from click.types import _NumberRangeBase
from click.exceptions import BadParameter


class ConcreteNumberRange(_NumberRangeBase):
    def __init__(self, min=None, max=None):
        super().__init__(min, max)
        self._number_class = int

    def convert(self, value, param, ctx):
        return super().convert(value, param, ctx)


def test_convert_format_error_message_uses_original_value():
    converter = ConcreteNumberRange(min=1, max=10)

    with pytest.raises(BadParameter) as excinfo:
        converter.convert("abc", None, None)

    message = str(excinfo.value)
    assert "abc" in message
    assert "None" not in message
